class Solution:
    def maxXor(self, nums):
        basis = [0] * 30
        for x in nums:
            for b in range(29, -1, -1):
                if not (x >> b) & 1: continue
                if not basis[b]:
                    basis[b] = x
                    break
                x ^= basis[b]
        res = 0
        for b in range(29, -1, -1):
            res = max(res, res ^ basis[b])
        return res

