class Solution:
    def maxXor(self, nums):
        basis = []
        for x in sorted(nums, reverse=True):
            for b in basis:
                x = min(x, x ^ b)
            if x:
                basis.append(x)
                basis.sort(reverse=True)
        res = 0
        for b in basis:
            res = max(res, res ^ b)
        return res

