class Solution {
public:
    int maxXor(vector<int>& nums) {
        vector<int> basis;
        vector<int> srt = nums;
        sort(srt.rbegin(), srt.rend());
        for (int x : srt) {
            for (int b : basis) x = min(x, x ^ b);
            if (x) { basis.push_back(x); sort(basis.rbegin(), basis.rend()); }
        }
        int res = 0;
        for (int b : basis) res = max(res, res ^ b);
        return res;
    }
};

