class Solution {
    public int maxXor(int[] nums) {
        List<Integer> basis = new ArrayList<>();
        int[] srt = nums.clone();
        Arrays.sort(srt);
        for (int i = srt.length - 1; i >= 0; i--) {
            int x = srt[i];
            for (int b : basis) x = Math.min(x, x ^ b);
            if (x != 0) { basis.add(x); basis.sort(Collections.reverseOrder()); }
        }
        int res = 0;
        for (int b : basis) res = Math.max(res, res ^ b);
        return res;
    }
}

