var maxXor = function(nums) {
    const basis = [];
    for (const x of [...nums].sort((a, b) => b - a)) {
        let v = x;
        for (const b of basis) v = Math.min(v, v ^ b);
        if (v) { basis.push(v); basis.sort((a, b) => b - a); }
    }
    let res = 0;
    for (const b of basis) res = Math.max(res, res ^ b);
    return res;
};
